var n=`0846-baingan-bharta`;var a=`world-0846`;var i=`IN`;var s=`south-asia`;var o=4;var g=58;var r={en:`Baingan Bharta`,ua:`Байган бхарта`};var d={en:`Baingan Bharta is a India dish made with eggplant, yellow onion, ginger-garlic paste, tomato. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Байган бхарта, страва кухні країни Індія. Основні складники: баклажан, жовта цибуля, імбирно-часникова паста, помідор. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var l=[{en:`Cut the vegetables evenly and roast at 200°C for about 35 minutes until tender and lightly charred.`,ua:`Наріжте овочі рівномірно та запікайте при 200°C приблизно 35 хвилин до м’якості й легкої підпеченої скоринки.`,t:[`roasting`],m:35,i:[[`eggplant`,830,`g`],[`canola-oil`,30,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 12 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 12 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:12,i:[[`yellow-onion`,180,`g`],[`ginger-garlic-paste`,25,`g`],[`tomato`,350,`g`],[`ground-cumin`,5,`g`],[`ground-coriander`,5,`g`]]},{en:`Shred or tear the cooked components, then fold together with the listed additions.`,ua:`Нашаткуйте або розберіть готові компоненти на волокна й змішайте з зазначеними додатками.`,t:[`shredding`,`mixing`],m:8,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`cilantro`,20,`g`],[`table-salt`,null,`to_taste`]]}];var h={slug:n,id:a,country:`IN`,region:s,servings:4,minutes:58,title:r,text:d,steps:l};export{i as country,h as default,a as id,g as minutes,s as region,o as servings,n as slug,l as steps,d as text,r as title};